//! Raw dataset deletion enters the real observed native attribute removal.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_raw_deletion_actual_attribute_attr_identity_and_old_value_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,key='x\ud800B',name='data-x\ud800-b';n.setAttributeNS(null,name,'old\udfff');var a=n.getAttributeNodeNS(null,name),watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});if(!delete d[key]||(n.getAttributeNS(null,name)!==null)||Object.hasOwn(d,key)||d[key]!==undefined||a.ownerElement!==null||a.value!=='old\udfff')throw 'actual native removal and Attr detachment';var r=watch.takeRecords();if(r.length!==1||r[0].type!=='attributes'||r[0].target!==n||r[0].attributeName!==name||r[0].attributeNamespace!==null||r[0].oldValue!=='old\udfff')throw 'actual raw old-value record';"#);}

#[test]
fn dataset_raw_deletion_restores_inherited_getter_without_invoking_it(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,key='x\ud800',p=DOMStringMap.prototype,hits=0;Object.defineProperty(p,key,{get:function(){hits++;return this;},configurable:true});n.setAttributeNS(null,'data-x\ud800','native');if(!delete d[key]||hits||Object.hasOwn(d,key)||d[key]!==d||hits!==1)throw 'native removal restores author prototype';if(!delete d[key]||hits!==1||d[key]!==d||hits!==2)throw 'absent deletion ignores inherited getter';"#);}

#[test]
fn dataset_raw_deletion_absent_unsupported_and_namespace_keys_are_noops(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-x\ud800-b','native');n.setAttributeNS('urn:foreign','q:data-z\ud800','foreign');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});for(var key of ['absent\ud800','x\ud800-b','z\ud800'])if(!delete d[key])throw 'absent/unsupported deletion';if(watch.takeRecords().length||n.getAttributeNS(null,'data-x\ud800-b')!=='native'||n.getAttributeNS('urn:foreign','data-z\ud800')!=='foreign')throw 'no native mutation';"#);}

#[test]
fn dataset_raw_deletion_html_svg_and_projection_names_remain_distinct(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset;n.setAttributeNS(null,'data-x\ud800','raw');n.setAttributeNS(null,'data-x\ufffd','scalar');if(!delete d['x\ud800']||(n.getAttributeNS(null,'data-x\ud800')!==null)||d['x\ufffd']!=='scalar'||!Object.hasOwn(d,'x\ufffd'))throw 'exact native deletion';}"#);}

#[test]
fn dataset_raw_deletion_bypasses_author_remove_shadow_and_converts_key_once(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,calls=0;n.setAttributeNS(null,'data-x\ud800','native');n.removeAttribute=function(){throw 'author shadow';};var key={toString:function(){calls++;return 'x\ud800';}};if(!delete d[key]||calls!==1||(n.getAttributeNS(null,'data-x\ud800')!==null))throw 'native path and once binding';var thrown={},seen=false;try{delete d[{toString:function(){throw thrown;}}];}catch(e){seen=e===thrown;}if(!seen||!delete d['absent\ud800'])throw 'abrupt identity and recovery';"#);}

#[test]
fn dataset_raw_deletion_native_name_copy_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-x\ud800','old\udfff');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();p.state.copy_work=0;let error=p.runtime.execute(r#"delete d['x\ud800'];"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(!error.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||d['x\ud800']!=='old\udfff')throw 'refusal unchanged';if(!delete d['x\ud800']||Object.hasOwn(d,'x\ud800'))throw 'recovery';var r=watch.takeRecords();if(r.length!==1||r[0].oldValue!=='old\udfff')throw 'recovery native record';"#);}
